pub fn rail_lower_bg(height: u32, drawer_open: bool) -> String {
    let mut rows = String::new();
    let cycle = ["#EEEEEE", "#E7E7E7", "#F0F0F0", "#FCFCFC"];
    for y in 0..height {
        let col = cycle[(y as usize) % 4];
        rows.push_str(&format!(r#"<rect x="0" y="{y}" width="23" height="1" fill="{col}"/>"#));
    }
    let left_col = if drawer_open { "#0A0A0A" } else { "#919191" };
    format!(
        r##"<div class="rib-bg"><svg width="23" height="{height}" viewBox="0 0 23 {height}">{rows}<rect x="0" y="0" width="1" height="{height}" fill="{left_col}"/><rect x="1" y="0" width="1" height="{height}" fill="#FEFEFE"/><rect x="2" y="0" width="1" height="{height}" fill="#F0F0F0"/><rect x="20" y="0" width="1" height="{height}" fill="#ECECEC"/><rect x="21" y="0" width="1" height="{height}" fill="#AEAEAE"/><rect x="22" y="0" width="1" height="{height}" fill="#040404"/></svg></div>"##
    )
}
